-- Migration to update the returns table status check constraint
-- Dropping the default constraint generated by PostgreSQL (usually tablename_columnname_check)
ALTER TABLE returns DROP CONSTRAINT IF EXISTS returns_status_check;
-- Add the updated constraint encompassing all canonical statuses
-- First, migrate any existing rows that use the old 'decision_ready' status to 'inspected'
UPDATE returns SET status = 'inspected' WHERE status = 'decision_ready';

ALTER TABLE returns ADD CONSTRAINT returns_status_check CHECK (
  status IN (
    'processing',
    'inspected',
    'accepted',
    'standard_refund',
    'relisted',
    'rejected',
    'completed'
  )
);
